/**
 * Per-model processing-stage benchmark (R2-1), on the experiment page
 * index.exp-stages.html generated by gen_pages.py.
 *
 * After the start button is clicked:
 *   1. every file of every model (.glb, or .gltf plus its .bin and images) is
 *      downloaded into memory, so that the stages below exclude network time;
 *   2. for each model in turn, on an otherwise idle page:
 *        parse      GLTFLoader.parseAsync (JSON/binary parsing, buffer and
 *                   accessor setup, image decoding, material creation)
 *        integrate  A-Frame scene integration: entity.setObject3D('mesh', model)
 *        compile    renderer.compile: shader program compilation
 *        upload     renderer.initTexture for every texture (GPU texture upload)
 *        draw       first render of the model alone (geometry buffer upload and
 *                   first draw), followed by gl.finish()
 *      Each stage reports its wall time and the main-thread time it blocks:
 *      integrate/compile/upload/draw are synchronous, so they block for their
 *      whole duration; parse is asynchronous, so its blocking time is the time
 *      covered by long tasks (> 50 ms) observed while it runs.
 * Results: window.__exp.stages; window.__exp.done = true at the end.
 */
(function () {
  'use strict';

  var CONFIG = window.__EXP_CONFIG__ || {};
  var exp = window.__exp = {
    version: 1,
    page: CONFIG,
    userAgent: navigator.userAgent,
    devicePixelRatio: window.devicePixelRatio,
    viewport: [window.innerWidth, window.innerHeight],
    startTime: null,
    ttff: null,
    stages: [],
    errors: [],
    ready: false,
    done: false
  };

  var longTasks = [];
  try {
    new PerformanceObserver(function (list) {
      list.getEntries().forEach(function (e) { longTasks.push([e.startTime, e.startTime + e.duration]); });
    }).observe({ entryTypes: ['longtask'] });
  } catch (e) { exp.errors.push('longtask observer unavailable'); }

  function now () { return performance.now(); }
  function nextFrame () { return new Promise(function (resolve) { requestAnimationFrame(function () { resolve(); }); }); }
  function idle (ms) { return new Promise(function (resolve) { setTimeout(resolve, ms); }); }

  function blockedMs (t0, t1) {
    var total = 0;
    longTasks.forEach(function (lt) { total += Math.max(0, Math.min(lt[1], t1) - Math.max(lt[0], t0)); });
    return total;
  }

  async function timed (fn, sync) {
    var t0 = now();
    var value = await fn();
    var t1 = now();
    if (sync) { return { value: value, wallMs: t1 - t0, blockedMs: t1 - t0 }; }
    await idle(200); // let the long-task observer deliver the entries of this stage
    return { value: value, wallMs: t1 - t0, blockedMs: blockedMs(t0, t1) };
  }

  function resolveUrl (base, uri) { return new URL(uri, new URL(base, location.href)).href; }

  async function fetchBuffer (url) {
    var res = await fetch(url);
    if (!res.ok) { throw new Error(res.status + ' ' + url); }
    return res.arrayBuffer();
  }

  // Download every file of a model into memory; returns {main, files: url -> blob URL, bytes}.
  async function preload (src) {
    var url = resolveUrl(location.href, src);
    var main = await fetchBuffer(url);
    var files = {};
    var bytes = main.byteLength;
    if (/\.gltf$/i.test(src)) {
      var json = JSON.parse(new TextDecoder().decode(main));
      var uris = [];
      (json.buffers || []).forEach(function (b) { if (b.uri && !/^data:/.test(b.uri)) { uris.push(b.uri); } });
      (json.images || []).forEach(function (i) { if (i.uri && !/^data:/.test(i.uri)) { uris.push(i.uri); } });
      for (var k = 0; k < uris.length; k++) {
        var depUrl = resolveUrl(url, uris[k]);
        var buf = await fetchBuffer(depUrl);
        bytes += buf.byteLength;
        files[depUrl] = URL.createObjectURL(new Blob([buf]));
      }
    }
    return { url: url, main: main, files: files, bytes: bytes };
  }

  function collectTextures (root) {
    var set = new Set();
    root.traverse(function (o) {
      var mats = o.material ? (Array.isArray(o.material) ? o.material : [o.material]) : [];
      mats.forEach(function (m) {
        Object.keys(m).forEach(function (k) { if (m[k] && m[k].isTexture) { set.add(m[k]); } });
      });
    });
    return Array.from(set);
  }

  async function profileModel (model, scene) {
    var THREE = AFRAME.THREE;
    var renderer = scene.renderer;
    var gl = renderer.getContext();
    var data = await preload(model.src);

    var manager = new THREE.LoadingManager();
    manager.setURLModifier(function (u) { return data.files[u] || u; });
    var loader = new THREE.GLTFLoader(manager);
    var base = data.url.substring(0, data.url.lastIndexOf('/') + 1);

    await idle(50);
    var parse = await timed(function () { return loader.parseAsync(data.main, base); });
    var gltf = parse.value;
    var root = gltf.scene || gltf.scenes[0];
    root.animations = gltf.animations;

    await idle(50);
    var entity = document.createElement('a-entity');
    scene.appendChild(entity);
    await new Promise(function (resolve) {
      if (entity.hasLoaded) { resolve(); } else { entity.addEventListener('loaded', resolve, { once: true }); }
    });
    var integrate = await timed(function () { entity.setObject3D('mesh', root); }, true);

    // Render the model alone, framed by a camera in front of its bounding box.
    var solo = new THREE.Scene();
    var box = new THREE.Box3().setFromObject(root);
    var size = box.getSize(new THREE.Vector3()).length() || 1;
    var center = box.getCenter(new THREE.Vector3());
    var cam = new THREE.PerspectiveCamera(60, renderer.domElement.width / renderer.domElement.height, size / 100, size * 10);
    cam.position.copy(center).add(new THREE.Vector3(0, 0, size));
    cam.lookAt(center);
    solo.add(new THREE.AmbientLight(0xffffff, 1));
    entity.removeObject3D('mesh');
    solo.add(root);

    await idle(50);
    var compile = await timed(function () { renderer.compile(solo, cam); gl.finish(); }, true);
    var textures = collectTextures(root);
    await idle(50);
    var upload = await timed(function () {
      textures.forEach(function (t) { renderer.initTexture(t); });
      gl.finish();
    }, true);
    await idle(50);
    var draw = await timed(function () { renderer.render(solo, cam); gl.finish(); }, true);

    var stats = { meshes: 0, triangles: 0 };
    root.traverse(function (o) {
      if (o.isMesh) {
        stats.meshes += 1;
        var g = o.geometry;
        stats.triangles += g.index ? g.index.count / 3 : (g.attributes.position ? g.attributes.position.count / 3 : 0);
      }
    });

    solo.remove(root);
    scene.removeChild(entity);
    Object.keys(data.files).forEach(function (k) { URL.revokeObjectURL(data.files[k]); });

    function pick (r) { return { wallMs: r.wallMs, blockedMs: r.blockedMs }; }
    return {
      id: model.id, src: model.src, priority: model.priority, bytes: data.bytes,
      textures: textures.length, meshes: stats.meshes, triangles: stats.triangles,
      parse: pick(parse), integrate: pick(integrate), compile: pick(compile), upload: pick(upload), draw: pick(draw)
    };
  }

  async function run () {
    var scene = document.querySelector('a-scene');
    if (!scene.hasLoaded) { await new Promise(function (r) { scene.addEventListener('loaded', r, { once: true }); }); }
    // Stop A-Frame's own render loop so that only the measured work runs.
    scene.renderer.setAnimationLoop(null);
    await nextFrame();
    var models = CONFIG.models || [];
    for (var i = 0; i < models.length; i++) {
      try {
        exp.stages.push(await profileModel(models[i], scene));
      } catch (e) {
        exp.errors.push(models[i].id + ': ' + (e && e.message ? e.message : e));
      }
      await idle(200);
    }
    exp.ttff = 0;
    exp.done = true;
  }

  function init () {
    var button = document.getElementById('ttff-start-button');
    button.addEventListener('click', function () {
      if (exp.startTime !== null) { return; }
      exp.startTime = now();
      button.style.display = 'none';
      run().catch(function (e) { exp.errors.push(String(e && e.stack || e)); exp.done = true; });
    });
    exp.ready = true;
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
